async def act(page):
    """
    From the Dashboard, navigate to Manage Products, find Desiree's black fitness t-shirt size XS,
    increase its price by 37%, and click Save (Save is the last action because it navigates away).
    """
    # There are no knowledge_base helper functions available; all actions use Playwright API calls directly.

    # 1) Navigate to Manage Products (relative URL)
    await page.goto("/index.php/admin/catalog_product/index/")
    await page.wait_for_load_state("networkidle")

    # 2) Use the Search group textbox to filter for "fitness" if available (use full group path)
    try:
        if await page.get_by_role("group", name="Search").count() > 0:
            search_group = page.get_by_role("group", name="Search")
            if await search_group.get_by_role("textbox").count() > 0:
                await search_group.get_by_role("textbox").first.fill("fitness")
                # Try to click a search-like button inside the Search group
                for btn_name in ("Search", "Filter", "Go"):
                    if await search_group.get_by_role("button", name=btn_name).count() > 0:
                        await search_group.get_by_role("button", name=btn_name).first.click()
                        break
        else:
            # Fallback: try a textbox named "Name"
            name_tb = page.get_by_role("textbox", name="Name")
            if await name_tb.count() > 0:
                await name_tb.first.fill("fitness")
                for btn_name in ("Search", "Filter", "Go"):
                    if await page.get_by_role("button", name=btn_name).count() > 0:
                        await page.get_by_role("button", name=btn_name).first.click()
                        break
    except Exception:
        # If filtering fails, continue — we'll search the grid rows directly
        pass

    await page.wait_for_load_state("networkidle")

    # 3) Inspect product grid rows to find Desiree's black XS fitness t-shirt
    rows = page.get_by_role("row")
    try:
        row_count = await rows.count()
    except Exception:
        row_count = 0

    target_row = None
    keywords = ["desiree", "black", "xs"]

    for i in range(row_count):
        r = rows.nth(i)
        try:
            txt = (await r.inner_text()).lower()
        except Exception:
            txt = ""
        if all(k in txt for k in keywords):
            target_row = r
            break

    if target_row is None:
        # final fallback: require 'desiree' and 'fitness'
        for i in range(row_count):
            r = rows.nth(i)
            try:
                txt = (await r.inner_text()).lower()
            except Exception:
                txt = ""
            if "desiree" in txt and "fitness" in txt:
                target_row = r
                break

    if target_row is None:
        raise Exception("Could not locate the product row for Desiree's black fitness t-shirt size XS.")

    # 4) From that row, get the product link href and navigate to the edit page using goto
    if await target_row.get_by_role("link").count() == 0:
        raise Exception("Product row did not contain a link to the edit page.")
    product_link = target_row.get_by_role("link").first
    href = await product_link.get_attribute("href")
    if href:
        await page.goto(href)
        await page.wait_for_load_state("networkidle")
    else:
        # If no href, clicking is the only option; clicking will navigate away so make it the last action
        await product_link.click()
        return

    # 5) Locate the Price input (several fallbacks)
    price_input = None
    try:
        if await page.get_by_role("textbox", name="Price").count() > 0:
            price_input = page.get_by_role("textbox", name="Price").first
    except Exception:
        price_input = None

    if price_input is None:
        try:
            if await page.get_by_label("Price").count() > 0:
                price_input = page.get_by_label("Price").first
        except Exception:
            price_input = None

    if price_input is None:
        # Scan textboxes for attributes containing 'price'
        textboxes = page.get_by_role("textbox")
        try:
            tb_count = await textboxes.count()
        except Exception:
            tb_count = 0
        for i in range(tb_count):
            tb = textboxes.nth(i)
            aria = (await tb.get_attribute("aria-label") or "").lower()
            name_attr = (await tb.get_attribute("name") or "").lower()
            placeholder = (await tb.get_attribute("placeholder") or "").lower()
            id_attr = (await tb.get_attribute("id") or "").lower()
            if "price" in aria or "price" in name_attr or "price" in placeholder or "price" in id_attr:
                price_input = tb
                break

    if price_input is None:
        raise Exception("Could not find the price input on the product edit page.")

    # 6) Read current price, compute +37%, fill new value
    raw_val = await price_input.input_value()
    cleaned = raw_val.replace("$", "").replace(",", "").strip()
    try:
        current_price = float(cleaned)
    except Exception:
        import re

        m = re.search(r"[0-9]+(?:\.[0-9]+)?", cleaned)
        if not m:
            raise Exception(f"Unable to parse current price from '{raw_val}'")
        current_price = float(m.group(0))

    new_price = round(current_price * 1.37, 2)
    await price_input.fill(str(new_price))

    # 7) Click Save (final action because it will navigate away)
    if await page.get_by_role("button", name="Save").count() > 0:
        await page.get_by_role("button", name="Save").first.click()
        return
    if await page.get_by_role("button", name="Save and Continue Edit").count() > 0:
        await page.get_by_role("button", name="Save and Continue Edit").first.click()
        return

    # Fallback: find any button whose visible text contains 'save'
    buttons = page.get_by_role("button")
    try:
        btn_count = await buttons.count()
    except Exception:
        btn_count = 0
    for i in range(btn_count):
        b = buttons.nth(i)
        try:
            txt = (await b.inner_text() or "").lower()
        except Exception:
            txt = ""
        if "save" in txt:
            await b.click()
            return

    raise Exception("Could not find a Save button to submit the product form.")

